import { NextRequest, NextResponse } from "next/server";
import { readFileSync, statSync } from "fs";
import { join } from "path";

const PMTILES_PATH = join(process.cwd(), "public", "data", "powergrid.pmtiles");

export async function GET(request: NextRequest) {
  const range = request.headers.get("range");
  const stat = statSync(PMTILES_PATH);
  const fileSize = stat.size;

  if (range) {
    const parts = range.replace(/bytes=/, "").split("-");
    const start = parseInt(parts[0], 10);
    const end = parts[1] ? parseInt(parts[1], 10) : Math.min(start + 1024 * 1024, fileSize - 1);
    const chunkSize = end - start + 1;

    // Read only the requested chunk
    const fd = require("fs").openSync(PMTILES_PATH, "r");
    const buffer = Buffer.alloc(chunkSize);
    require("fs").readSync(fd, buffer, 0, chunkSize, start);
    require("fs").closeSync(fd);

    return new NextResponse(buffer, {
      status: 206,
      headers: {
        "Content-Range": `bytes ${start}-${end}/${fileSize}`,
        "Accept-Ranges": "bytes",
        "Content-Length": String(chunkSize),
        "Content-Type": "application/octet-stream",
        "Access-Control-Allow-Origin": "*",
        "Cache-Control": "public, max-age=86400",
      },
    });
  }

  // Full file request (shouldn't happen with PMTiles, but just in case)
  return new NextResponse(null, {
    status: 200,
    headers: {
      "Accept-Ranges": "bytes",
      "Content-Length": String(fileSize),
      "Content-Type": "application/octet-stream",
      "Access-Control-Allow-Origin": "*",
    },
  });
}
